mapper.select:
SELECT CASE WHEN COUNT(1) > 0 THEN 1 ELSE 0 END
FROM permissions
WHERE permission_url = #{urlPattern}
  AND permission_method = #{method}

SELECT COUNT(1)
FROM project_members pm
         JOIN project_member_roles pmr ON pm.project_member_id = pmr.project_member_id
         JOIN role_permissions rp ON pmr.role_id = rp.role_id
         JOIN permissions p ON rp.permission_id = p.permission_id
WHERE pm.user_id = #{userId}
  AND pm.project_id = #{projectId}
  AND p.permission_method = #{method}
  AND p.permission_url = #{url}


SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
FROM projects p
         LEFT JOIN project_members pm ON p.project_id = pm.project_id AND pm.user_id = #{userId}
WHERE p.project_id = #{projectId}
  AND (
    p.is_public = 'P1'           -- 조건 1: 전체 공개 프로젝트이거나
        OR pm.user_id IS NOT NULL    -- 조건 2: 멤버 테이블에 내 ID가 존재하거나
    )

SELECT CASE WHEN COUNT(1) > 0 THEN 1 ELSE 0 END
FROM groups g
    JOIN roles r ON r.role_name = g.group_name
         JOIN role_permissions rp ON r.role_id = rp.role_id
         JOIN permissions p ON rp.permission_id = p.permission_id
WHERE g.group_id = #{groupId}
  AND p.permission_url = #{targetUrl}
  AND p.permission_method = #{method}
